void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 4096;

    // Perform phase reset based on local_best heuristic
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            // Reset saved phases to favor local best assignments
            saved[i] = local_best[i] != 0 ? local_best[i] : (rand() % 2 ? 1 : -1);
        }
    }
}
